<template>
 <span><el-button v-hasPermi="['wmsInventory:inventory:list','channelInventory:inventory:list','ruleStock:info:list']" type="text" size="small" @click="open">福袋保障与回收</el-button>
 <el-dialog :title="`福袋库存 · ${sku}`" :visible.sync="visible" width="min(1180px,96vw)" append-to-body :close-on-click-modal="false"><div v-loading="loading"><el-alert v-if="error" title="保障记录加载失败，请刷新核对" type="warning" :closable="false"/><template v-if="data"><p>{{ data.notice }}</p><el-button size="small" @click="load">刷新核对</el-button>
 <h4>渠道保障（袋）</h4><el-table :data="data.pools" row-key="id" size="small"><el-table-column type="expand"><template slot-scope="s"><p>原分货：{{ s.row.rule_name || s.row.rule_id }} · 规则 v{{ s.row.revision }}</p><el-table :data="s.row.components" size="mini"><el-table-column prop="sku_sn" label="实际 SKU"/><el-table-column prop="batch_code" label="原批次"/><el-table-column v-for="c in pieces" :key="c.key" :prop="c.key" :label="c.name+'（件）'" width="100"/></el-table></template></el-table-column><el-table-column prop="id" label="保障编号" width="100"/><el-table-column prop="channel_id" label="渠道 ID" width="100"/><el-table-column prop="store_code" label="原发货仓" min-width="120"/><el-table-column v-for="c in bags" :key="c.key" :prop="c.key" :label="c.name+'（袋）'" width="100"/><el-table-column label="状态" width="130"><template slot-scope="s">{{ states[s.row.state] || s.row.state }}</template></el-table-column><el-table-column label="操作" width="140"><template slot-scope="s"><el-button v-if="s.row.state!=='DRAINED'" v-hasPermi="['ruleStock:info:edit']" type="text" :disabled="busy || !!Number(s.row.daily_enabled)" @click="reclaim(s.row)">{{ s.row.state==='DRAINING' ? '继续核对回收' : '停止投放并回收' }}</el-button><span v-if="Number(s.row.daily_enabled)">先停用日常规则</span></template></el-table-column></el-table>
 <h4>平台曝光保护（袋）</h4><p>结果不明、暂停链接仍占保护。回收后请运行原同步组清零，再确认未处理订单后继续核对回收。</p><el-table :data="data.exposures" size="small" empty-text="尚无平台投放记录"><el-table-column prop="channel_id" label="渠道 ID"/><el-table-column prop="group_id" label="原同步组"/><el-table-column prop="quantity" label="仍可能售出（袋）"/><el-table-column label="核对状态"><template slot-scope="s">{{ Number(s.row.uncertain) ? '结果未确认，保留保障' : '已完成本次核对' }}</template></el-table-column><el-table-column prop="update_time" label="核对时间" min-width="170"/></el-table>
 </template></div></el-dialog></span>
</template>
<script>
import request from '@/utils/request'
export default { name:'LuckyBagLedger', props:{sku:{type:String,required:true},channelId:{type:[String,Number],default:0}},data:()=>({visible:false,loading:false,busy:false,error:false,data:null,sequence:0,states:{ACTIVE:'可投放',DRAINING:'等待安全回收',DRAINED:'已回收'},bags:[{key:'quantity',name:'原保障'},{key:'available_quantity',name:'未占用'},{key:'occupied_quantity',name:'订单占用'},{key:'consumed_quantity',name:'已发'},{key:'released_quantity',name:'已回收'}],pieces:[{key:'quantity',name:'原保障'},{key:'occupied_quantity',name:'订单占用'},{key:'consumed_quantity',name:'已发'},{key:'released_quantity',name:'已回收'}]}),beforeDestroy(){this.sequence++},watch:{sku(){this.sequence++;this.visible=false;this.data=null}},methods:{open(){this.visible=true;this.load()},async load(){const seq=++this.sequence;this.loading=true;this.error=false;try{const r=await request({url:`/inventory/lucky-bags/${encodeURIComponent(this.sku)}`,params:{channelId:this.channelId}});if(seq===this.sequence)this.data=r.data}catch(_){if(seq===this.sequence)this.error=true}finally{if(seq===this.sequence)this.loading=false}},async reclaim(row){if(this.busy)return;try{await this.$confirm('本操作停止原分货单中此福袋的全部渠道保障继续投放。平台清零及未处理订单核对完成后，才释放原组件；已有订单保留原来源。','回收福袋保障',{type:'warning'})}catch(_){return}this.busy=true;try{const r=await request({url:`/inventory/lucky-bags/${encodeURIComponent(this.sku)}/release`,method:'post',data:{rule_id:row.rule_id,confirmed:true}});this.$message.info(r.data.state==='RELEASED'?'可释放保障已回收':'已停止投放，仍有平台或订单保护待核对');await this.load()}finally{this.busy=false}}}}
</script>
